internal class UPSBasePriceCalculator
{
    private static UPSBasePriceCalculator instance;
    private static boolean writeCalculationLog;
    private UPSVendListPriceView vendListPriceView;

}

Method.Source:
static void TypeNew()
{
    instance = new UPSBasePriceCalculator();
}

public static UPSBasePriceCalculator Instance(boolean _writeCalculationLog = false)
{
    writeCalculationLog = _writeCalculationLog;

    return UPSBasePriceCalculator::instance;
}

private void fetchMostSpecificVendorListPrices(boolean _crossCompany = false)
{
    if (_crossCompany)
    {
        select crosscompany * from vendListPriceView;
    }
    else
    {
        select * from vendListPriceView;
    }
}
